// Synthetic input: a mix of codes an API really returns under load.
// 429 and 5xx are worth retrying. 4xx client errors are not.
return [429, 503, 200, 401, 404, 200].map((code, i) => ({
  json: { requestId: `req-${i + 1}`, statusToSimulate: code }
}));

// Retryable vs permanent. Retrying a 401 three times does not fix the
// credential; it just delays the alert by three attempts.
const RETRYABLE = new Set([408, 425, 429, 500, 502, 503, 504]);

return $input.all().map(item => {
  const status = item.json.statusCode;
  const headers = item.json.headers ?? {};
  // Honour the server's own instruction when it gives one.
  const retryAfterRaw = headers['retry-after'] ?? headers['Retry-After'] ?? null;
  const retryAfterSeconds = retryAfterRaw === null ? null : Number(retryAfterRaw);

  return {
    json: {
      status,
      retryable: RETRYABLE.has(status),
      retryAfterSeconds: Number.isFinite(retryAfterSeconds) ? retryAfterSeconds : null,
      action: RETRYABLE.has(status)
        ? (retryAfterSeconds ? `wait ${retryAfterSeconds}s, then retry` : 'back off and retry')
        : 'do not retry - alert a human'
    }
  };
});
